// The midsegment of a scalene triangle. P and Q are the midpoints of AB and AC,
// so PQ is parallel to BC and exactly half as long. One tick mark on each half of
// AB and two on each half of AC carry the midpoint claim without the caption.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(340,250);
pen e = black + 1.1pt;
pen m = rgb(0.13,0.33,0.62) + 1.8pt;
pair A=(0,0), B=(9,0), C=(2.6,6.2);
pair P=(4.5,0), Q=(1.3,3.1);
pair v[] = {(0,0),(9,0),(2.6,6.2),(4.5,0),(1.3,3.1)};
draw(A--B--C--cycle, e);
draw(P--Q, m);
// one tick on each half of AB
draw((2.25,-0.13)--(2.25,0.13), black+0.9pt);
draw((6.75,-0.13)--(6.75,0.13), black+0.9pt);
// two ticks on each half of AC, perpendicular to AC
draw((0.735,1.417)--(0.495,1.517), black+0.9pt);
draw((0.805,1.583)--(0.565,1.683), black+0.9pt);
draw((2.035,4.517)--(1.795,4.617), black+0.9pt);
draw((2.105,4.683)--(1.865,4.783), black+0.9pt);
for (int i = 0; i < 5; ++i) dot(v[i], black+2.4pt);
label("$A$", A, S);
label("$B$", B, S);
label("$C$", C, N);
label("$P$", P, S);
label("$Q$", Q, W);
label("$PQ\parallel BC$", (4.9,1.5), N);

// The same criterion read two ways. Each panel sets one scalene triangle above a
// second copy of it, with one tick mark on every side of all four triangles, so the
// correspondence A B C to G H J on the left and K L M to P Q R on the right is
// visible. Left: the copy is the same size, an equals sign between them, congruent.
// Right: the copy is half the size, a k label between them, similar. The tick marks
// are identical in both panels; only the size of the copy changes.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(340,275);
pen e = black + 1.1pt;
pair A=(0,3.2), B=(3.2,3.2), C=(1.1,5.6);
pair G=(0,0), H=(3.2,0), J=(1.1,2.4);
pair K=(5.2,3.2), L=(8.4,3.2), M=(6.3,5.6);
pair P=(5.2,0), Q=(6.8,0), R=(5.75,1.2);
path tik[] = {(1.6,-0.12)--(1.6,0.12),(2.2403,1.2789)--(2.0597,1.1211),(0.6591,1.15)--(0.4409,1.25),(1.6,3.08)--(1.6,3.32),(2.2403,4.4789)--(2.0597,4.3211),(0.6591,4.35)--(0.4409,4.45),(6.0,-0.12)--(6.0,0.12),(6.3653,0.679)--(6.1847,0.521),(5.5841,0.55)--(5.3659,0.65),(6.8,3.08)--(6.8,3.32),(7.4403,4.4789)--(7.2597,4.3211),(5.8591,4.35)--(5.6409,4.45)};
pair vt[] = {(0,3.2),(3.2,3.2),(1.1,5.6),(0,0),(3.2,0),(1.1,2.4),(5.2,3.2),(8.4,3.2),(6.3,5.6),(5.2,0),(6.8,0),(5.75,1.2)};
string topl[] = {"$C$","$M$"};
pair topat[] = {(1.1,5.6),(6.3,5.6)};
string botl[] = {"$A$","$B$","$G$","$H$","$K$","$L$","$P$","$Q$"};
pair botat[] = {(0,3.2),(3.2,3.2),(0,0),(3.2,0),(5.2,3.2),(8.4,3.2),(5.2,0),(6.8,0)};
draw(A--B--C--cycle, e);
draw(G--H--J--cycle, e);
draw(K--L--M--cycle, e);
draw(P--Q--R--cycle, e);
for (int i = 0; i < 12; ++i) draw(tik[i], black+0.9pt);
for (int i = 0; i < 12; ++i) dot(vt[i], black+2.3pt);
for (int i = 0; i < 2; ++i) label(topl[i], topat[i], N);
for (int i = 0; i < 8; ++i) label(botl[i], botat[i], S);
label("$=$", (1.6,2.8));
label("$k=\frac{1}{2}$", (7.4,2.4), N);
label("congruent", (1.6,6.4), N);
label("similar", (6.8,6.4), N);

// The altitude to the hypotenuse. The right angle is at C, the hypotenuse AB is
// horizontal, and CD is dropped to D on AB. The two smaller right triangles are
// shaded two different colours so the three-way similarity ACD, CDB, ABC reads
// off the picture: AD = 4.5, DB = 8, CD = 6, AC = 7.5, BC = 10, AB = 12.5.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(400,210);
pen e = black + 1.2pt;
pair A=(0,0), B=(12.5,0), C=(4.5,6), D=(4.5,0);
filldraw(A--C--D--cycle, rgb(0.87,0.91,0.97));
filldraw(C--B--D--cycle, rgb(0.97,0.90,0.84));
draw(A--B--C--cycle, e);
draw(C--D, e);
// the right angle at C
draw((4.2,5.6)--(4.6,5.3)--(4.9,5.7), e);
dot(A, black+2.4pt);
dot(B, black+2.4pt);
dot(C, black+2.4pt);
dot(D, black+2.4pt);
label("$A$", A, S);
label("$B$", B, S);
label("$C$", C, N);
label("$D$", D, S);
label("$AD$", (2.25,0.35), S);
label("$DB$", (8.5,0.35), S);
label("$CD$", (4.15,3.0), W);

// In an isosceles triangle the apex segment is all three at once. One tick on each
// sloping side shows AB = AC; one tick on each half of the base shows BD = DC; the
// square at D shows AD perpendicular to BC. Together those make AD the median, the
// altitude, and the bisector of the apex angle, which is what the three notes read.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(360,218);
pen e = black + 1.2pt;
pen m = rgb(0.13,0.33,0.62) + 1.7pt;
pair A=(0,5.4), B=(-3.6,0), C=(3.6,0), D=(0,0);
// one tick on each sloping side, perpendicular to it
draw((-1.8998,2.7666)--(-1.7002,2.6334), black+0.9pt);
draw((1.8998,2.7666)--(1.7002,2.6334), black+0.9pt);
// one tick on each half of the base
draw((-1.8,-0.13)--(-1.8,0.13), black+0.9pt);
draw((1.8,-0.13)--(1.8,0.13), black+0.9pt);
draw(B--A--C--cycle, e);
draw(A--D, m);
draw((0.5,0)--(0.5,0.5)--(0,0.5), e);
dot(A, black+2.4pt);
dot(B, black+2.4pt);
dot(C, black+2.4pt);
dot(D, black+2.4pt);
label("$A$", A, N);
label("$B$", B, S);
label("$C$", C, S);
label("$D$", D, S);
label("$AD$", (0,2.7), W);
label("median: $BD = DC$", (6.4,5.6), W);
label("altitude: $AD\perp BC$", (6.4,4.8), W);
label("bisector of $\angle A$", (6.4,4.0), W);
